<script setup lang="ts">
definePageMeta({ middleware: 'admin' })
const db = useSupabaseClient()
type Issue = { id:string; reference_number:number; title:string; description:string; category:string; priority:string; status:string; area:string; assigned_to:string; resolution:string; created_at:string; updated_at:string; created_by:string }
type IssueComment = {id:string; issue_id:string; comment:string; created_at:string}
const issues = ref<Issue[]>([])
const comments = ref<IssueComment[]>([])
const loading = ref(true), busy = ref(false), error = ref(''), success = ref('')
const selected = ref<Issue|null>(null), showCreate = ref(false)
const search = ref(''), statusFilter = ref('all'), categoryFilter = ref('all')
const draft = reactive({title:'',description:'',category:'improvement',priority:'medium',area:'General',assigned_to:''})
const edit = reactive({title:'',description:'',category:'improvement',priority:'medium',status:'new',area:'General',assigned_to:'',resolution:''})
const newComment = ref('')
const categories = ['fault','improvement','idea','task']
const priorities = ['low','medium','high','critical']
const statuses = ['new','in_progress','on_hold','resolved','closed']
const label = (value:string) => value.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())
const stats = computed(()=>({total:issues.value.length,open:issues.value.filter(x=>!['resolved','closed'].includes(x.status)).length,urgent:issues.value.filter(x=>['high','critical'].includes(x.priority)&&!['resolved','closed'].includes(x.status)).length,done:issues.value.filter(x=>['resolved','closed'].includes(x.status)).length}))
const visible = computed(()=>issues.value.filter(x=> (statusFilter.value==='all'||x.status===statusFilter.value) && (categoryFilter.value==='all'||x.category===categoryFilter.value) && `${x.reference_number} ${x.title} ${x.description} ${x.area} ${x.assigned_to}`.toLowerCase().includes(search.value.toLowerCase())))
const date = (v:string)=>new Date(v).toLocaleDateString('en-AU',{day:'numeric',month:'short',year:'numeric'})
function selectIssue(issue:Issue){selected.value=issue;Object.assign(edit,{title:issue.title,description:issue.description,category:issue.category,priority:issue.priority,status:issue.status,area:issue.area,assigned_to:issue.assigned_to,resolution:issue.resolution});newComment.value='';void loadComments(issue.id)}
async function load(){loading.value=true;error.value='';const {data,error:e}=await db.from('management_issues').select('*').order('created_at',{ascending:false});issues.value=(data||[]) as Issue[];if(e)error.value=e.message;loading.value=false}
async function loadComments(id:string){const {data,error:e}=await db.from('management_issue_comments').select('id,issue_id,comment,created_at').eq('issue_id',id).order('created_at',{ascending:true});comments.value=(data||[]) as IssueComment[];if(e)error.value=e.message}
async function createIssue(){if(busy.value)return;error.value='';success.value='';if(draft.title.trim().length<3){error.value='Enter a title of at least 3 characters.';return}busy.value=true;try{const {data:{user}}=await db.auth.getUser();if(!user)throw new Error('Sign in again.');const {data,error:e}=await db.from('management_issues').insert({title:draft.title.trim(),description:draft.description.trim(),category:draft.category,priority:draft.priority,area:draft.area.trim()||'General',assigned_to:draft.assigned_to.trim(),created_by:user.id}).select('*').single();if(e)throw e;showCreate.value=false;Object.assign(draft,{title:'',description:'',category:'improvement',priority:'medium',area:'General',assigned_to:''});await load();if(data)selectIssue(data as Issue);success.value='Issue created.'}catch(e:any){error.value=e.message||'Unable to create issue.'}finally{busy.value=false}}
async function saveIssue(){if(!selected.value||busy.value)return;error.value='';success.value='';busy.value=true;try{const {data:{user}}=await db.auth.getUser();if(!user)throw new Error('Sign in again.');const {error:e}=await db.from('management_issues').update({title:edit.title.trim(),description:edit.description.trim(),category:edit.category,priority:edit.priority,status:edit.status,area:edit.area.trim()||'General',assigned_to:edit.assigned_to.trim(),resolution:edit.resolution.trim(),updated_by:user.id}).eq('id',selected.value.id);if(e)throw e;const id=selected.value.id;await load();const updated=issues.value.find(x=>x.id===id);if(updated)selectIssue(updated);success.value='Changes saved.'}catch(e:any){error.value=e.message||'Unable to save changes.'}finally{busy.value=false}}
async function addComment(){if(!selected.value||!newComment.value.trim()||busy.value)return;error.value='';busy.value=true;try{const {data:{user}}=await db.auth.getUser();if(!user)throw new Error('Sign in again.');const {error:e}=await db.from('management_issue_comments').insert({issue_id:selected.value.id,comment:newComment.value.trim(),created_by:user.id});if(e)throw e;newComment.value='';await loadComments(selected.value.id)}catch(e:any){error.value=e.message||'Unable to add comment.'}finally{busy.value=false}}
onMounted(load)
</script>
<template>
  <div class="issues-page">
    <div class="crumb">Dashboard <span>›</span> Administration <span>›</span> Improvements &amp; Faults</div>
    <div class="heading"><div><div class="eyebrow">PLATFORM MANAGEMENT</div><h1>Improvements &amp; Faults Log</h1><p>Record issues, collect ideas and track work through to resolution.</p></div><button class="primary" @click="showCreate=true;selected=null">＋ New Item</button></div>
    <div class="stats"><div class="metric"><span>Total Items</span><strong>{{stats.total}}</strong></div><div class="metric"><span>Open Items</span><strong>{{stats.open}}</strong></div><div class="metric"><span>High / Critical Open</span><strong>{{stats.urgent}}</strong></div><div class="metric"><span>Resolved / Closed</span><strong>{{stats.done}}</strong></div></div>
    <div v-if="error" class="alert" role="alert">{{error}}</div><div v-if="success" class="notice" role="status">{{success}}</div>
    <div class="workgrid"><section class="panel"><div class="panel-title"><h2>Issue Register</h2><button class="subtle" @click="load">↻ Refresh</button></div><div class="filters"><input v-model="search" placeholder="Search number, title, area…" aria-label="Search issues"><select v-model="statusFilter" aria-label="Filter status"><option value="all">All statuses</option><option v-for="s in statuses" :key="s" :value="s">{{label(s)}}</option></select><select v-model="categoryFilter" aria-label="Filter category"><option value="all">All types</option><option v-for="c in categories" :key="c" :value="c">{{label(c)}}</option></select></div><p v-if="loading" class="muted">Loading issues…</p><p v-else-if="!visible.length" class="muted">No matching issues. Create the first item to start the log.</p><div v-else class="issue-list"><button v-for="item in visible" :key="item.id" class="issue-row" :class="{active:selected?.id===item.id}" @click="showCreate=false;selectIssue(item)"><span class="issue-top"><strong>#{{item.reference_number}} · {{item.title}}</strong><span class="pill" :class="item.priority">{{label(item.priority)}}</span></span><span class="issue-bottom"><span>{{label(item.category)}} · {{item.area}}</span><span>{{label(item.status)}}</span></span><small>{{date(item.created_at)}}<template v-if="item.assigned_to"> · {{item.assigned_to}}</template></small></button></div></section>
    <section class="panel detail"><template v-if="showCreate"><div class="panel-title"><h2>New Item</h2><button class="subtle" @click="showCreate=false">Close</button></div><form class="editor" @submit.prevent="createIssue"><label>Title<input v-model="draft.title" maxlength="180" required minlength="3" placeholder="What needs attention?"></label><label>Description<textarea v-model="draft.description" rows="5" placeholder="Describe the problem, idea or requested change"></textarea></label><div class="twocol"><label>Type<select v-model="draft.category"><option v-for="c in categories" :key="c" :value="c">{{label(c)}}</option></select></label><label>Priority<select v-model="draft.priority"><option v-for="p in priorities" :key="p" :value="p">{{label(p)}}</option></select></label></div><div class="twocol"><label>Area / Module<input v-model="draft.area" placeholder="e.g. Competitions"></label><label>Assigned to<input v-model="draft.assigned_to" placeholder="Name or team"></label></div><button class="primary" type="submit" :disabled="busy">{{busy?'Saving…':'Create Item'}}</button></form></template>
    <template v-else-if="selected"><div class="panel-title"><h2>Item #{{selected.reference_number}}</h2><button class="subtle" @click="selected=null">Close</button></div><form class="editor" @submit.prevent="saveIssue"><label>Title<input v-model="edit.title" required minlength="3" maxlength="180"></label><label>Description<textarea v-model="edit.description" rows="4"></textarea></label><div class="twocol"><label>Type<select v-model="edit.category"><option v-for="c in categories" :key="c" :value="c">{{label(c)}}</option></select></label><label>Priority<select v-model="edit.priority"><option v-for="p in priorities" :key="p" :value="p">{{label(p)}}</option></select></label></div><div class="twocol"><label>Status<select v-model="edit.status"><option v-for="s in statuses" :key="s" :value="s">{{label(s)}}</option></select></label><label>Assigned to<input v-model="edit.assigned_to"></label></div><label>Area / Module<input v-model="edit.area"></label><label>Resolution / Outcome<textarea v-model="edit.resolution" rows="3" placeholder="What was changed or decided?"></textarea></label><button class="primary" type="submit" :disabled="busy">{{busy?'Saving…':'Save Changes'}}</button></form><div class="discussion"><h3>Comments &amp; Updates</h3><p v-if="!comments.length" class="muted">No comments yet.</p><div v-for="c in comments" :key="c.id" class="comment"><p>{{c.comment}}</p><small>{{date(c.created_at)}}</small></div><form @submit.prevent="addComment"><textarea v-model="newComment" rows="3" maxlength="4000" placeholder="Add a progress note or discussion comment" required></textarea><button class="subtle" type="submit" :disabled="busy||!newComment.trim()">Add Comment</button></form></div></template>
    <div v-else class="empty"><span>🛠️</span><h2>Select an item</h2><p>Choose an issue from the register to view details, update its status or add comments.</p></div></section></div>
  </div>
</template>
<style scoped>
.issues-page{color:#eaf3ff;max-width:1600px;margin:auto}.crumb{font-size:12px;color:#78b8ff;margin-bottom:18px}.crumb span{padding:0 10px;color:#7993b2}.eyebrow{color:#73b9ff;letter-spacing:2px;font-size:10px;font-weight:700}.heading{display:flex;justify-content:space-between;gap:20px;align-items:center;margin-bottom:24px}.heading h1{font-size:clamp(25px,3vw,34px);margin:6px 0}.heading p{color:#a9c6e7;margin:0}.primary,.subtle{cursor:pointer;border-radius:9px;padding:11px 16px;font-weight:700}.primary{background:#0964cf;color:white;border:1px solid #3a95ff}.subtle{background:#173557;color:#dbeaff;border:1px solid #38618e}.stats{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin-bottom:20px}.metric,.panel{background:linear-gradient(140deg,#112e51,#0b213e);border:1px solid #315e8c;border-radius:14px}.metric{padding:18px 20px}.metric span{font-size:12px;color:#a9c9ed;display:block}.metric strong{font-size:32px;display:block;margin-top:7px}.workgrid{display:grid;grid-template-columns:minmax(300px,1fr) minmax(350px,1.2fr);gap:16px}.panel{padding:18px;min-width:0}.panel-title{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:15px}.panel h2{font-size:19px;margin:0}.filters{display:grid;grid-template-columns:1fr 145px 125px;gap:8px;margin-bottom:15px}.issues-page input,.issues-page select,.issues-page textarea{width:100%;box-sizing:border-box;background:#091c33;color:#f4f9ff;border:1px solid #42678e;border-radius:8px;padding:11px;font:inherit;min-width:0}.issues-page input:focus,.issues-page select:focus,.issues-page textarea:focus{outline:2px solid #4a9dff;outline-offset:1px}.issue-list{display:flex;flex-direction:column;gap:8px;max-height:680px;overflow:auto}.issue-row{width:100%;text-align:left;background:#0c2543;border:1px solid #2e537d;border-radius:10px;color:#e9f4ff;padding:14px;cursor:pointer}.issue-row:hover,.issue-row.active{background:#154779;border-color:#56a6ff}.issue-top,.issue-bottom{display:flex;align-items:center;justify-content:space-between;gap:8px}.issue-top strong{font-size:14px;overflow-wrap:anywhere}.issue-bottom{font-size:12px;color:#b9d2ee;margin:9px 0}.issue-row small,.comment small{color:#93b7df}.pill{font-size:10px;border:1px solid #3f6b9c;border-radius:999px;padding:4px 8px;white-space:nowrap}.pill.high,.pill.critical{color:#ffb6a8;border-color:#e16b63}.pill.low{color:#a8dfc5}.editor{display:flex;flex-direction:column;gap:14px}.editor label{display:block;color:#bad4f0;font-size:12px;font-weight:650}.editor label input,.editor label select,.editor label textarea{display:block;margin-top:6px;font-size:14px;font-weight:400}.twocol{display:grid;grid-template-columns:1fr 1fr;gap:12px}.discussion{margin-top:28px;border-top:1px solid #365c83;padding-top:15px}.discussion h3{font-size:16px}.comment{background:#0b2442;border-radius:9px;padding:10px 13px;margin:8px 0}.comment p{white-space:pre-wrap;margin:0 0 8px}.discussion form{display:grid;gap:10px;margin-top:14px}.discussion button{justify-self:start}.empty{text-align:center;padding:80px 25px;color:#abc9e8}.empty span{font-size:38px}.muted{color:#a9c6e7}.alert,.notice{padding:12px;border-radius:8px;margin-bottom:15px;background:#51252b;color:#ffd1d1}.notice{background:#153e33;color:#a8f3c7}@media(max-width:1150px){.workgrid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}}@media(max-width:650px){.heading{align-items:flex-start;flex-direction:column}.stats{gap:8px}.metric{padding:13px}.filters{grid-template-columns:1fr 1fr}.filters input{grid-column:1/-1}.twocol{grid-template-columns:1fr}.panel{padding:12px}}
</style>
